function solve(a){if(a.length===0||a[0].length===0){return 0;}const b=new Array(a[0].length).fill(0);let r=0;for(const x of a){for(let i=0;i<b.length;i+=1){b[i]=x[i]==='1'||x[i]===1?b[i]+1:0;}h(b,(x,y)=>{r=Math.max(r,x*y);});}return r;}function h(a,f){const r=[];for(let i=0;i<=a.length;i+=1){const b=i===a.length?0:a[i];while(r.length>0&&a[r[r.length-1]]>b){const x=r.pop();const y=r.length===0?0:r[r.length-1]+1;f(a[x],i-y);}if(i<a.length){r.push(i);}}}